double midpoint_integration(double (*f)(double), double a, double b, int N) {
    double dx = (b - a) / (double)N;
    double sum = 0.0;
    for (int i = 1; i <= N; i++) {
        double x_mid = a + (i - 0.5) * dx;
        sum += f(x_mid);
    }
    return dx * sum;
}
